@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + id : int
}

class IngredientDish {
  + quantity : float
}

class Table {
  + id : int
  + maxAmountOfPeople : int
}

class DishMeal {
  + timesServed : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

Ingredient "*" -- "*" Dish : composed of
Dish "*" -- "1" IngredientDish
Ingredient "1" -- "*" IngredientDish

Meal "1" -- "1" Table
Meal "1" -- "0..1" Client
Meal "1" -- "1" Waiter
Meal "1" -- "*" DishMeal
Dish "1" -- "*" DishMeal

@enduml

